<template><view class="page"><view class="card"><view class="field"><text class="field-label">活动名称</text><input v-model="form.title" class="input" /></view><view class="field"><text class="field-label">地点</text><input v-model="form.location" class="input" /></view><view v-for="f in times" :key="f.key" class="field"><text class="field-label">{{ f.label }}</text><input v-model="form[f.key]" class="input" placeholder="2026-09-01T09:00" /></view><view class="field"><text class="field-label">活动类型</text><picker :range="['公开活动','邀请制活动']" @change="form.visibility=Number($event.detail.value)===0?'PUBLIC':'INVITE_ONLY'"><view class="input">{{ form.visibility==='PUBLIC'?'公开活动':'邀请制活动' }}</view></picker></view><view class="field"><text class="field-label">费用说明</text><textarea v-model="form.feeRule" class="textarea" /></view><view class="field"><text class="field-label">活动说明</text><textarea v-model="form.description" class="textarea" /></view><button class="secondary-btn" @click="chooseCover">{{ cover?'已选择封面':'选择封面（可选）' }}</button><button class="primary-btn" :loading="loading" @click="submit">发布活动</button></view></view></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{api,upload}from'@/services/api';import{apiTime}from'@/utils/time';const loading=ref(false),cover=ref('');const form=reactive<any>({title:'',location:'',startTime:'',endTime:'',signupStart:'',signupEnd:'',visibility:'PUBLIC',feeRule:'',description:''});const times=[{key:'signupStart',label:'报名开始'},{key:'signupEnd',label:'报名结束'},{key:'startTime',label:'活动开始'},{key:'endTime',label:'活动结束'}];function chooseCover(){uni.chooseImage({count:1,sizeType:['compressed'],success:r=>cover.value=r.tempFilePaths[0]})}async function submit(){if(!form.title||!form.location||times.some(t=>!form[t.key]))return uni.showToast({title:'请填写名称、地点和全部时间',icon:'none'});loading.value=true;try{const payload={...form};times.forEach(t=>payload[t.key]=apiTime(payload[t.key]));const a=await api<any>('/activities','POST',payload);if(cover.value){try{await upload(`/activities/${a.id}/cover`,cover.value)}catch{uni.showToast({title:'活动已创建，封面可稍后补传',icon:'none'})}}uni.showToast({title:'发布成功'});setTimeout(()=>uni.redirectTo({url:`/pages/activityDetail/activityDetail?id=${a.id}`}),500)}finally{loading.value=false}}</script>
